import{_ as a,H as e,f as n,i as l}from"./chunks/framework.DLd0CbzH.js";const f=JSON.parse('{"title":"Верификация лидов (Human-in-the-loop) — Agelto","description":"","frontmatter":{"type":"workflow","tags":["agelto","workflow","verification","human-in-the-loop"],"created":"2026-06-11T00:00:00.000Z","updated":"2026-06-11T00:00:00.000Z"},"headers":[],"relativePath":"02_Workflow/Lead_Verification.md","filePath":"02_Workflow/Lead_Verification.md"}'),s={name:"02_Workflow/Lead_Verification.md"};function i(o,t,p,r,d,c){return e(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="верификация-лидов-human-in-the-loop-—-agelto" tabindex="-1">Верификация лидов (Human-in-the-loop) — Agelto <a class="header-anchor" href="#верификация-лидов-human-in-the-loop-—-agelto" aria-label="Permalink to &quot;Верификация лидов (Human-in-the-loop) — Agelto&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">Назначение</p><p>Процесс премодерации матчей до передачи лида в CRM. Гарантия точности ≥ 92% (NFR [[BRD (Agelto)]] §5), митигация галлюцинаций ИИ ([[Risk_Register (Agelto)]] R-1). Требования — F-MATCH-5/6/7.</p></div><hr><h2 id="поток" tabindex="-1">Поток <a class="header-anchor" href="#поток" aria-label="Permalink to &quot;Поток&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Матч (Match Score)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ confidence ≥ 92% ──→ авто-допуск к лиду → CRM / Radar</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ confidence &lt; 92% ──→ флаг «Требует проверки»</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>     Очередь премодерации (Analyst)</span></span>
<span class="line"><span>        ├─ подтверждён → лид допущен + строка в обучающую выборку</span></span>
<span class="line"><span>        └─ отклонён   → матч скрыт + строка в обучающую выборку</span></span></code></pre></div><p>Порог 92% настраивается per-клиент (F-MATCH-6).</p><h2 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Аспект</th><th style="text-align:left;">Правило</th></tr></thead><tbody><tr><td style="text-align:left;">SLA проверки</td><td style="text-align:left;">Цель: ≤ 4 рабочих часа (тендеры с коротким сроком подачи — приоритет). Финально — после P6</td></tr><tr><td style="text-align:left;">Очерёдность</td><td style="text-align:left;">Сортировка: дедлайн подачи ↑, потенциальная сумма ↓</td></tr><tr><td style="text-align:left;">Вердикты</td><td style="text-align:left;">Подтверждён / Отклонён / Отклонён с указанием верного кандидата (топ-3, F-MATCH-3a)</td></tr><tr><td style="text-align:left;">Active learning</td><td style="text-align:left;">Все вердикты — в обучающую выборку (F-MATCH-7, цель диплома: 50 000+ размеченных строк)</td></tr><tr><td style="text-align:left;">Контроль качества</td><td style="text-align:left;">Выборочная перепроверка N подтверждённых матчей/мес против golden dataset → метрика Accuracy в NFR</td></tr></tbody></table><h2 id="открыто" tabindex="-1">Открыто <a class="header-anchor" href="#открыто" aria-label="Permalink to &quot;Открыто&quot;">​</a></h2><ul><li><strong>P6</strong> ([[Открытые вопросы (Agelto)]]): кто Analyst — штат Agelto или менеджер клиента? Определяет unit-экономику тарифов и SLA</li><li>Периодичность дообучения/переиндексации по накопленной выборке — TBD</li></ul>`,10)])])}const g=a(s,[["render",i]]);export{f as __pageData,g as default};
